import React from 'react';

import { getHikingFieldsAsync } from '@apps/Hiking/@services/hiking.service';
import {
  deleteFoodActRecipeCategory,
  editFoodActRecipeCategoryForHiking,
  fillFoodActRecipeCategoriesForHiking,
  getFoodActsRecipeCategories,
  getFoodActsRecipeCategoriesForHiking,
} from '@apps/Hiking/@services/hikingMenu.service';
import { IFoodActsRecipeCategory } from '@apps/Hiking/@types/DTO/hikingMenu.dto.types';
import PageLoader from '@components/PageLoader';
import { confirm } from '@helpers/confirmHelper';
import notificationHelper from '@helpers/notificationHelper';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import PohCheckbox from '@ui-kit/Checkbox';
import PohIcon from '@ui-kit/Icon';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohInput, { InputTypes } from '@ui-kit/Input';
import InputSizes from '@ui-kit/Input/InputSizes';

const cols: Array<{
  title: string;
  field: keyof IFoodActsRecipeCategory;
  type?: 'checkbox' | 'remove' | 'number';
}> = [
  {
    title: 'Приём пищи',
    field: 'food_act_name',
  },
  {
    title: 'Категория',
    field: 'recipe_category_name',
  },
  {
    title: 'Увеличивать порцию',
    field: 'can_increase',
    type: 'checkbox',
  },
  {
    title: 'Можно дублировать',
    field: 'can_dublicate',
    type: 'checkbox',
  },
  {
    title: 'Мин. % от приема пищи',
    field: 'min_pct',
    type: 'number',
  },
  {
    title: 'Макс. % от приема пищи',
    field: 'max_pct',
    type: 'number',
  },
  {
    title: 'Важность',
    field: 'order_index',
    type: 'number',
  },
  {
    title: '',
    field: 'id',
    type: 'remove',
  },
];

const HikingMenuFoodActRecipesCategories: React.FC<{ id_hiking: number }> = ({ id_hiking }) => {
  const [isDefault, setIsDefault] = React.useState(false);
  const [loading, setLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [hikingName, setHikingName] = React.useState('');
  const [foodActsRecipesCategories, setFoodActsRecipesCategories] = React.useState<
    IFoodActsRecipeCategory[]
  >([]);

  React.useEffect(() => {
    const start = async () => {
      try {
        setLoading(true);
        const { name } = await getHikingFieldsAsync(id_hiking, 'name');
        let foodActsRecipesCategories1 =
          (await getFoodActsRecipeCategoriesForHiking(id_hiking)) || [];
        if (!foodActsRecipesCategories1.length) {
          foodActsRecipesCategories1 = await getFoodActsRecipeCategories();
          setIsDefault(true);
        }
        setHikingName(name ?? '');
        setFoodActsRecipesCategories(foodActsRecipesCategories1);
      } catch (error) {
        setErr(error as Error);
      } finally {
        setLoading(false);
      }
    };

    start();
  }, [id_hiking]);

  const handleDelete = async (id: string) => {
    try {
      await deleteFoodActRecipeCategory({ id_hiking, id });
      setFoodActsRecipesCategories((c) => c.filter((x) => x.id !== id));
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  const handleFillDefault = async () => {
    try {
      await fillFoodActRecipeCategoriesForHiking(id_hiking);
      const res = (await getFoodActsRecipeCategoriesForHiking(id_hiking)) || [];
      setFoodActsRecipesCategories(res);
      setIsDefault(false);
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  const handleEditField = async ({
    id,
    field,
    value,
  }: {
    id: string;
    field: string;
    value: string;
  }) => {
    try {
      await editFoodActRecipeCategoryForHiking({ id, id_hiking }, { [field]: value });
      setFoodActsRecipesCategories((c) =>
        c.map((x) => (x.id === id ? { ...x, [field]: value } : x)),
      );
    } catch (error) {
      notificationHelper.error((error as Error).message);
    }
  };

  if (loading) {
    return <PageLoader />;
  }
  if (err) {
    return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;
  }

  return (
    <div>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingName },
          { href: `/hiking/${id_hiking}/menu`, text: 'Меню' },
          {
            href: `/hiking/${id_hiking}/menu/acts`,
            text: 'Настройки актов приема пищи',
            active: true,
          },
        ]}
      />
      <h3 className="mb-3">Акты приема пищи</h3>
      <p>
        Добавьте и настройте категории блюд которые должны быть доступны в каждом приеме пищи «
        {hikingName}».
      </p>
      {isDefault && (
        <p>
          Это значения по умолчанию. Вы можете{' '}
          <PohButton onClick={handleFillDefault}>Отредактировать</PohButton>
        </p>
      )}
      {!isDefault && (
        <p className="text-end">
          <PohButton
            size={ButtonSize.Small}
            variant={ButtonVariant.Light}
            onClick={() => confirm('Сбросить на «По умолчанию»?') && handleFillDefault()}
          >
            Сбросить
          </PohButton>
        </p>
      )}
      <table className="table">
        <thead>
          <tr>
            {cols.map((col) => (
              <th key={col.field}>{col.title}</th>
            ))}
          </tr>
        </thead>
        <tbody>
          {foodActsRecipesCategories.map((row) => (
            <tr key={row.id}>
              {cols.map((col) => (
                <td key={col.field}>
                  {col.type === 'checkbox' && (
                    <PohCheckbox
                      checked={+row[col.field] === 1}
                      disabled={isDefault}
                      onChange={(checked) =>
                        handleEditField({
                          id: row.id,
                          field: col.field,
                          value: checked ? '1' : '0',
                        })
                      }
                    />
                  )}
                  {col.type === 'number' && (
                    <PohInput
                      type={InputTypes.number}
                      value={row[col.field]}
                      disabled={isDefault}
                      min={0}
                      max={100}
                      onRealChange={(value) =>
                        handleEditField({ id: row.id, field: col.field, value })
                      }
                      size={InputSizes.Small}
                    />
                  )}
                  {col.type === 'remove' && (
                    <PohButton
                      size={ButtonSize.Small}
                      className="float-end"
                      variant={ButtonVariant.Light}
                      onClick={() => handleDelete(row.id)}
                    >
                      <PohIcon name={IconsEnum.trash} />
                    </PohButton>
                  )}
                  {!col.type && row[col.field]}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default HikingMenuFoodActRecipesCategories;
